"""The portable package for waypoints (COORDINATION C1/C2), generated by
scripts/build-portable.py — never hand-edit portable/.

Pilot contracts (freshness, same-name manifest, no top-level bin/, closure, C2 schema,
deterministic zip) PLUS the waypoints-specific ones: the CLI moved bin/ -> scripts/ with
its root-module import closure (waypoints_core/menu/__init__) copied to the portable ROOT
(where bin/waypoints.py's sys.path insert looks for them), all bin/ references rewritten,
and a FUNCTIONAL proof that the portable CLI runs against an ISOLATED store
(WAYPOINTS_FILE in tmp — a smoke run without it once wrote into the real store).
"""
import hashlib
import json
import os
import re
import subprocess
import sys
import zipfile
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parent.parent
BUILD = ROOT / "scripts" / "build-portable.py"
PORTABLE = ROOT / "portable"

ADAPTATION_CLASSES = {"native-unchanged", "mechanical", "qualified-adapter",
                      "reduced-useful", "unsupported", "unknown"}
EVIDENCE_LEVELS = {"source-inspected", "fixture-tested", "runtime-qualified"}
REF_RE = re.compile(r"\$\{(CLAUDE_PLUGIN_ROOT|CLAUDE_SKILL_DIR)\}(?:/([^\s\"'\\]+))?")


def run_build(*args):
    return subprocess.run([sys.executable, str(BUILD), *args], capture_output=True,
                          text=True, cwd=ROOT, timeout=60)


def sha256(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def test_portable_dir_is_a_fresh_build():
    r = run_build("--check")
    assert r.returncode == 0, r.stdout + r.stderr


def test_portable_manifest_same_name_no_bin():
    m = json.loads((PORTABLE / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8"))
    host = json.loads((ROOT / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8"))
    assert m["name"] == host["name"] == "waypoints"
    assert m["version"] == host["version"]
    assert not (PORTABLE / "bin").exists()
    assert (PORTABLE / "scripts" / "waypoints.py").is_file()


def test_no_stale_bin_references_and_import_closure_at_root():
    # any waypoints.py mention that is not the scripts/ path is stale host guidance
    stale_re = re.compile(r"(?<!scripts/)(?<!hooks/)waypoints\.py")
    for p in sorted(PORTABLE.rglob("*")):
        if p.is_file() and p.suffix in (".json", ".sh", ".py", ".md") \
                and p.name != "PORTABLE-BUILD.json":  # its notes may name the old path
            text = p.read_text(encoding="utf-8", errors="replace")
            assert not stale_re.search(text), \
                f"stale host-PATH guidance in {p.relative_to(PORTABLE)}: {stale_re.search(text).group(0)}"
    for mod in ("waypoints_core.py", "waypoints_menu.py", "__init__.py"):
        assert (PORTABLE / mod).is_file(), f"import-closure module missing at portable root: {mod}"
    import ast as _ast
    cli_text = (PORTABLE / "scripts" / "waypoints.py").read_text(encoding="utf-8")
    _ast.parse(cli_text)  # the transformed portable CLI must still parse
    assert '"$CLAUDE_PLUGIN_ROOT/scripts/waypoints.py"' in cli_text, \
        "the moved CLI must invoke via the scripts/ path"


def test_host_to_portable_file_set_is_pinned():
    for s in sorted(ROOT.glob("skills/*/SKILL.md")):
        assert (PORTABLE / s.relative_to(ROOT)).is_file(), f"host skill missing: {s}"
    for c in sorted(ROOT.glob("commands/*.md")):
        assert (PORTABLE / c.relative_to(ROOT)).is_file(), f"host command missing: {c}"
    hooks = json.loads((ROOT / "hooks" / "hooks.json").read_text(encoding="utf-8"))
    for rel in re.findall(r"\$\{CLAUDE_PLUGIN_ROOT\}/([^\s\"'\\]+)", json.dumps(hooks)):
        assert (PORTABLE / rel).exists(), f"hook script missing: {rel}"


def test_portable_closure_complete_and_no_escapes():
    for p in sorted(PORTABLE.rglob("*")):
        assert not p.is_symlink()
    for p in sorted(PORTABLE.rglob("*")):
        if p.is_file() and p.suffix in (".json", ".sh", ".py", ".md"):
            text = p.read_text(encoding="utf-8", errors="replace")
            assert "../" not in text, f"literal ../ escape in {p.relative_to(PORTABLE)}"
            for m in REF_RE.finditer(text):
                rel = m.group(2)
                if rel is None:
                    continue
                parts = PurePosixPath(rel).parts
                assert ".." not in parts and not PurePosixPath(rel).is_absolute()
                assert (PORTABLE / rel).exists(), f"{p.relative_to(PORTABLE)} -> {rel} missing"


def test_portable_build_json_matches_c2_schema():
    d = json.loads((PORTABLE / "PORTABLE-BUILD.json").read_text(encoding="utf-8"))
    assert d["schema"] == "haiggoh-portable-build/1"
    for k in ("source_repo", "source_commit", "builder", "builder_version",
              "transform_version", "files", "components"):
        assert k in d, k
    assert d["source_repo"].endswith("/waypoints"), d["source_repo"]
    expected = {str(p.relative_to(PORTABLE)).replace("\\", "/") for p in PORTABLE.rglob("*")
                if p.is_file() and p.name != "PORTABLE-BUILD.json"
                and "__pycache__" not in p.parts}
    assert set(d["files"]) == expected
    for rel, h in d["files"].items():
        assert sha256(PORTABLE / rel) == h, rel
    assert d["components"]
    for c in d["components"]:
        assert {"path", "kind", "adaptation_class", "evidence_level", "surfaces"} <= set(c)
        assert c["adaptation_class"] in ADAPTATION_CLASSES
        assert c["evidence_level"] in EVIDENCE_LEVELS
        assert set(c["surfaces"]) == {"chat", "cowork", "code"}
        assert all(isinstance(v, bool) for v in c["surfaces"].values())
        assert (PORTABLE / c["path"]).exists(), c["path"]


def test_portable_cli_runs_against_an_isolated_store(tmp_path):
    """FUNCTIONAL proof the closure works: the portable CLI runs from the portable root,
    imports the PORTABLE core modules (probe: waypoints_core.__file__ must be under
    portable/ — with -I and a scrubbed PYTHONPATH the host repo cannot leak in), and
    honours WAYPOINTS_FILE (a smoke run without that override once wrote a test item
    into the real ~/.claude/waypoints.json)."""
    store = tmp_path / "w.json"
    env = {k: v for k, v in os.environ.items() if k != "PYTHONPATH"}
    env["WAYPOINTS_FILE"] = str(store)
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    cli = PORTABLE / "scripts" / "waypoints.py"
    probe = subprocess.run(
        [sys.executable, "-I", "-c",
         "import sys; sys.path.insert(0, sys.argv[1]); import waypoints_core; print(waypoints_core.__file__)",
         str(PORTABLE)],
        capture_output=True, text=True, env=env, cwd=tmp_path, timeout=30)
    assert probe.returncode == 0, probe.stderr
    assert str(PORTABLE) in probe.stdout, f"core module leaked from outside portable/: {probe.stdout}"
    r = subprocess.run([sys.executable, "-I", str(cli), "add", "portable smoke", "--id", "p-smoke"],
                       capture_output=True, text=True, env=env, cwd=tmp_path, timeout=30)
    assert r.returncode == 0, r.stderr
    assert store.is_file(), "the CLI must write the WAYPOINTS_FILE store, not the real one"
    r2 = subprocess.run([sys.executable, "-I", str(cli), "list"], capture_output=True, text=True,
                        env=env, cwd=tmp_path, timeout=30)
    assert "p-smoke" in r2.stdout, r2.stdout
    real = Path.home() / ".claude" / "waypoints.json"
    if real.exists():
        d = json.loads(real.read_text())
        items = d.get("items", d) if isinstance(d, dict) else d
        vals = items if isinstance(items, list) else list(items.values())
        assert not any(isinstance(i, dict) and i.get("id") == "p-smoke" for i in vals), \
            "real store must stay untouched"


def test_zip_is_deterministic_manifest_at_root_and_side_effect_free(tmp_path):
    before = {str(p.relative_to(PORTABLE)): sha256(p) for p in PORTABLE.rglob("*") if p.is_file()}
    r1 = run_build("--zip", "--out", str(tmp_path / "a"))
    r2 = run_build("--zip", "--out", str(tmp_path / "b"))
    assert r1.returncode == 0 and r2.returncode == 0
    za, zb = tmp_path / "a" / "waypoints-portable.zip", tmp_path / "b" / "waypoints-portable.zip"
    assert za.read_bytes() == zb.read_bytes()
    names = zipfile.ZipFile(za).namelist()
    assert ".claude-plugin/plugin.json" in names
    assert "scripts/waypoints.py" in names and not any(n.startswith("bin/") for n in names)
    for mod in ("waypoints_core.py", "waypoints_menu.py", "__init__.py"):
        assert mod in names, f"import-closure module missing from zip: {mod}"
    assert not any(n.startswith("portable/") or "\\" in n for n in names)
    after = {str(p.relative_to(PORTABLE)): sha256(p) for p in PORTABLE.rglob("*") if p.is_file()}
    assert before == after
